const lv_image_dsc_t *ui_icon_find(const char *key)
{
    if (strcmp(key, "files") == 0) return &icon_files_dsc;
    if (strcmp(key, "music") == 0) return &icon_music_dsc;
    if (strcmp(key, "pomodoro") == 0) return &icon_pomodoro_dsc;
    if (strcmp(key, "reader") == 0) return &icon_reader_dsc;
    if (strcmp(key, "settings") == 0) return &icon_settings_dsc;
    if (strcmp(key, "sub") == 0) return &icon_sub_dsc;
    if (strcmp(key, "weather") == 0) return &icon_weather_dsc;
    if (strcmp(key, "chat") == 0) return &icon_chat_dsc;
    if (strcmp(key, "muse") == 0) return &icon_muse_dsc;
    if (strcmp(key, "xiaozhi") == 0) return &icon_xiaozhi_dsc;
    return NULL;
}
